import{_ as t,o,c as a,ag as r}from"./chunks/framework.B7PviQjB.js";const s="/docs/images/collaborate/trash-undo-toast.png",n="/docs/images/collaborate/trash-page.png",g=JSON.parse('{"title":"Delete and restore documents","description":"Move documents to the Trash, restore them, and delete them forever.","frontmatter":{"title":"Delete and restore documents","description":"Move documents to the Trash, restore them, and delete them forever.","type":"how-to"},"headers":[],"relativePath":"collaborate/trash.md","filePath":"collaborate/trash.md"}'),l={name:"collaborate/trash.md"};function i(h,e,d,c,m,u){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="delete-and-restore-documents" tabindex="-1">Delete and restore documents <a class="header-anchor" href="#delete-and-restore-documents" aria-label="Permalink to &quot;Delete and restore documents&quot;">​</a></h1><p>Deleted documents go to the workspace&#39;s Trash, where you can restore them or delete them for good.</p><p>Each workspace has its own Trash. Nothing in it is deleted automatically.</p><div class="info custom-block"><p class="custom-block-title">Before you start</p><ul><li>To move a document to the Trash, restore it, or delete it forever, you need to have created it, or own the workspace.</li><li>While a document is in the Trash, nobody can open it, and its share links and template stop working. Restoring brings them back.</li></ul></div><h2 id="move-a-document-to-the-trash" tabindex="-1">Move a document to the Trash <a class="header-anchor" href="#move-a-document-to-the-trash" aria-label="Permalink to &quot;Move a document to the Trash&quot;">​</a></h2><ol><li>On the documents list, click <strong>⋯</strong> at the end of the document&#39;s row.</li><li>Select <strong>Move to Trash</strong>.</li></ol><p>A message says <em>Moved “&lt;title&gt;” to Trash</em>. Click <strong>Undo</strong> in it within 10 seconds to put the document back.</p><p>To trash several documents, select them with the checkboxes and click <strong>Move to Trash</strong> in the bar above the list.</p><p><img src="'+s+'" alt="Documents list with the Moved &quot;Q3 budget&quot; to Trash message and its Undo button"></p><h2 id="restore-a-document" tabindex="-1">Restore a document <a class="header-anchor" href="#restore-a-document" aria-label="Permalink to &quot;Restore a document&quot;">​</a></h2><ol><li>In the sidebar, click <strong>Trash</strong>.</li><li>Click <strong>Restore</strong> in the document&#39;s row.</li></ol><p>The document goes back to the folder it was in. If that folder was deleted, it goes to the top of the workspace.</p><p><img src="'+n+'" alt="Trash page with a board, a doc, and sheets, the Deleted column, and Restore and Delete forever on each row"></p><h3 id="on-a-phone" tabindex="-1">On a phone <a class="header-anchor" href="#on-a-phone" aria-label="Permalink to &quot;On a phone&quot;">​</a></h3><p><strong>Restore</strong> and <strong>Delete forever</strong> show as icons only, and the <strong>Deleted</strong> column is hidden. Tap the circular-arrow icon to restore, or the trash icon with an X to delete forever.</p><h2 id="delete-a-document-forever" tabindex="-1">Delete a document forever <a class="header-anchor" href="#delete-a-document-forever" aria-label="Permalink to &quot;Delete a document forever&quot;">​</a></h2><div class="danger custom-block"><p class="custom-block-title">This can&#39;t be undone</p><p>The document can no longer be opened or restored, and its share links stop working for good.</p></div><ol><li>In the sidebar, click <strong>Trash</strong>.</li><li>Click <strong>Delete forever</strong> in the document&#39;s row.</li><li>In the confirmation, click <strong>Delete forever</strong>.</li></ol><h2 id="empty-the-trash" tabindex="-1">Empty the Trash <a class="header-anchor" href="#empty-the-trash" aria-label="Permalink to &quot;Empty the Trash&quot;">​</a></h2><ol><li>In the sidebar, click <strong>Trash</strong>.</li><li>Click <strong>Empty trash</strong>.</li><li>In <strong>Empty trash?</strong>, click <strong>Empty trash</strong>.</li></ol><p>Every document you can manage is deleted forever. Documents that other people created stay in the Trash for their author or a workspace owner.</p><h2 id="known-limitations" tabindex="-1">Known limitations <a class="header-anchor" href="#known-limitations" aria-label="Permalink to &quot;Known limitations&quot;">​</a></h2><ul><li>Deleted folders don&#39;t go to the Trash. Their documents move to the top of the workspace instead. See <a href="/docs/collaborate/folders.html#delete-a-folder">Folders</a>.</li><li>Deleting a workspace deletes its documents without using the Trash.</li><li>Trashed documents don&#39;t appear in search or the documents list until you restore them.</li></ul><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/docs/collaborate/folders.html">Folders</a> to organize what you keep.</li><li><a href="/docs/collaborate/version-history.html">Version history</a> to undo changes inside a document instead.</li><li><a href="/docs/collaborate/share.html">Share a document</a> for what happens to links.</li><li><a href="/docs/collaborate/workspaces.html#check-what-each-role-can-do">Workspaces and roles</a> for who can delete.</li></ul>',25)])])}const f=t(l,[["render",i]]);export{g as __pageData,f as default};
